/**
 * components/AttentionHeatmap.js
 * Bottom row: Regime gauge card + Model metrics card
 * (Named AttentionHeatmap to match existing file structure)
 */

import React from 'react';
import './AttentionHeatmap.css';

/* ── REGIME GAUGE SVG ─────────────────────────────────── */
function RegimeGauge({ regime }) {
  const map   = { Calm: { color:'#00e87a', pct:0.18 }, Trending: { color:'#00d2ff', pct:0.5 }, Volatile: { color:'#ff3b6b', pct:0.85 } };
  const { color, pct } = map[regime] || map['Trending'];
  const R = 68, cx = 80, cy = 78;
  const a1 = Math.PI;
  const a2 = a1 + pct * Math.PI;
  const x1 = cx + R * Math.cos(a1), y1 = cy + R * Math.sin(a1);
  const x2 = cx + R * Math.cos(a2), y2 = cy + R * Math.sin(a2);
  return (
    <svg width="160" height="92" viewBox="0 0 160 92">
      <path d={`M ${cx-R} ${cy} A ${R} ${R} 0 0 1 ${cx+R} ${cy}`}
        fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="8" strokeLinecap="round"/>
      <path d={`M ${x1} ${y1} A ${R} ${R} 0 ${pct > 0.5 ? 1 : 0} 1 ${x2} ${y2}`}
        fill="none" stroke={color} strokeWidth="8" strokeLinecap="round"
        style={{ filter:`drop-shadow(0 0 8px ${color})` }}/>
      <circle cx={x2} cy={y2} r="5" fill={color} style={{ filter:`drop-shadow(0 0 6px ${color})` }}/>
      <text x={cx-R+2}   y={cy+16} fill="#3a4558" fontSize="8" fontFamily="JetBrains Mono,monospace">CALM</text>
      <text x={cx-8}     y={cy+16} fill="#3a4558" fontSize="8" fontFamily="JetBrains Mono,monospace">TREND</text>
      <text x={cx+R-30}  y={cy+16} fill="#3a4558" fontSize="8" fontFamily="JetBrains Mono,monospace">VOLAT</text>
    </svg>
  );
}

/* ── REGIME CARD ──────────────────────────────────────── */
function RegimeCard({ regime }) {
  const name = regime?.regime_name || regime?.name || 'Trending';
  const desc = regime?.description ||
    (name === 'Calm'     && 'Low volatility — stable conditions. Confidence boosted +5%.') ||
    (name === 'Trending' && 'Directional movement detected. Confidence unchanged.')        ||
    (name === 'Volatile' && 'High uncertainty — confidence reduced -15%. Use caution.');
  const adjConf = regime?.adjusted_model_confidence || 0;

  return (
    <div className="ah-card center">
      <div className="ah-hdr">
        <div className="ah-ico amber">📡</div>
        <div className="ah-title">Market Regime</div>
      </div>
      <RegimeGauge regime={name} />
      <div className={`regime-name regime-${name.toLowerCase()}`}>
        {name.toUpperCase()}
      </div>
      <div className="regime-desc">{desc}</div>
      {adjConf > 0 && (
        <div className="regime-conf">
          Adjusted confidence: <span>{(adjConf * 100).toFixed(1)}%</span>
        </div>
      )}
    </div>
  );
}

/* ── METRICS CARD ─────────────────────────────────────── */
const METRICS = [
  { l:'MAE',        v:'$6.72', u:'per step' },
  { l:'RMSE',       v:'$8.08', u:'per step' },
  { l:'R² Score',   v:'0.667', u:'explained var' },
  { l:'Parameters', v:'298K',  u:'trainable' },
  { l:'Train Seqs', v:'576+',  u:'sequences' },
  { l:'Lookback',   v:'60',    u:'days' },
];

function MetricsCard() {
  return (
    <div className="ah-card">
      <div className="ah-hdr">
        <div className="ah-ico green">📊</div>
        <div className="ah-title">Model Metrics</div>
      </div>
      <div className="met-grid">
        {METRICS.map((m, i) => (
          <div key={i} className="met-cell">
            <div className="met-lbl">{m.l}</div>
            <div className="met-val">{m.v}</div>
            <div className="met-unit">{m.u}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ── EXPORT ──────────────────────────────────────────── */
export default function AttentionHeatmap({ regime }) {
  return (
    <div className="ah-row">
      <RegimeCard  regime={regime} />
      <MetricsCard />
    </div>
  );
}
